CREATE EXTENSION pg_buffercache;
CREATE TABLE orders (
  order_id    bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  customer_id int     NOT NULL,
  amount      numeric(10,2) NOT NULL,
  status      text    NOT NULL DEFAULT 'new',
  created_at  timestamptz NOT NULL DEFAULT now()
);
INSERT INTO orders (customer_id, amount)
SELECT (random()*999)::int + 1, round((random()*5000)::numeric, 2)
FROM generate_series(1, 200000);

CHECKPOINT;
SELECT pg_stat_reset_shared('checkpointer');
SELECT pg_stat_reset_shared('bgwriter');
SELECT pg_size_pretty(pg_table_size('orders')) AS table_size;
UPDATE orders SET status = 'paid' WHERE order_id % 10 = 0;
SELECT buffers_used, buffers_dirty, buffers_unused
  FROM pg_buffercache_summary();

\timing on
CHECKPOINT;
SELECT buffers_used, buffers_dirty FROM pg_buffercache_summary();

SELECT num_timed, num_requested, num_done, buffers_written,
       slru_written, write_time, sync_time
  FROM pg_stat_checkpointer;

SELECT pg_stat_reset_shared('checkpointer');

INSERT INTO orders (customer_id, amount)
SELECT (random()*999)::int + 1, round((random()*5000)::numeric, 2)
FROM generate_series(1, 1000000);

SELECT num_timed, num_requested,
       round(100.0 * num_requested / NULLIF(num_timed + num_requested, 0), 1) AS pct_requested,
       buffers_written,
       round((write_time + sync_time) / 1000) AS io_seconds,
       stats_reset::timestamp(0)
  FROM pg_stat_checkpointer;

